use std::collections::HashMap;

pub fn get_or_insert<'a>(map: &'a mut HashMap<u32, String>, key: u32) -> &'a str {
    if let Some(v) = map.get(&key) {
        return v;
    }
    map.insert(key, String::from("default"));
    map.get(&key).unwrap()
}

