use std::cell::Cell;

pub struct Invariant<'l>(Cell<&'l ()>);

fn create_invariant<'l>() -> Invariant<'l> {
    Invariant(Cell::new(&()))
}

pub fn flow_sensitive_invariance<'a, 'b>(choice: bool) -> Result<Invariant<'a>, Invariant<'b>> {
